CREATE TABLE REVENUESTATISTICSSYSTEM.IDENTITIES (SUBJECT VARCHAR(200) PRIMARY KEY, ISSUER VARCHAR(250) NOT NULL, ORGANIZATION VARCHAR(100) NOT NULL, USERNAME VARCHAR(100) NOT NULL, DISPLAY_NAME VARCHAR(200), LAST_LOGIN TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE REVENUESTATISTICSSYSTEM.MODULES (MODULE_KEY VARCHAR(30) PRIMARY KEY, NAME VARCHAR(100) NOT NULL, ICON VARCHAR(10), DESCRIPTION VARCHAR(300), COLUMNS_JSON VARCHAR(2000), ENABLED INT DEFAULT 1, SORT_ORDER INT);
CREATE TABLE REVENUESTATISTICSSYSTEM.REVENUE_RECORDS (ID VARCHAR(64) PRIMARY KEY, MODULE_KEY VARCHAR(30) NOT NULL REFERENCES REVENUESTATISTICSSYSTEM.MODULES(MODULE_KEY), BUSINESS_DATE VARCHAR(10) NOT NULL, CATEGORY VARCHAR(400) NOT NULL, QUANTITY INT NOT NULL CHECK(QUANTITY>=0), AMOUNT_CENTS BIGINT NOT NULL CHECK(AMOUNT_CENTS>=0), VISITORS INT DEFAULT 0 CHECK(VISITORS>=0), SOURCE VARCHAR(400), NOTE VARCHAR(2000), VERSION INT DEFAULT 1, CREATED_BY VARCHAR(200), CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UPDATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX REVENUESTATISTICSSYSTEM.IDX_REVENUE_DATE ON REVENUESTATISTICSSYSTEM.REVENUE_RECORDS(BUSINESS_DATE,MODULE_KEY);
CREATE TABLE REVENUESTATISTICSSYSTEM.SETTINGS (ID INT PRIMARY KEY, SCENIC_NAME VARCHAR(800), SCENIC_LEVEL VARCHAR(1200), ADMIN_DEPARTMENT VARCHAR(400), VERSION INT DEFAULT 1);
INSERT INTO REVENUESTATISTICSSYSTEM.SETTINGS VALUES(1,'安徽寿县古城景区','国家历史文化名城核心区 · 全国重点文保单位','运营管理部',1);
CREATE TABLE REVENUESTATISTICSSYSTEM.INTEGRATIONS (ID VARCHAR(64) PRIMARY KEY, NAME VARCHAR(400) NOT NULL, MODULE_KEY VARCHAR(30) NOT NULL REFERENCES REVENUESTATISTICSSYSTEM.MODULES(MODULE_KEY), TOKEN_HASH VARCHAR(64) NOT NULL, ENABLED INT DEFAULT 1, CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE REVENUESTATISTICSSYSTEM.AUDIT_LOG (ID VARCHAR(64) PRIMARY KEY, ACTOR VARCHAR(200), ACTION VARCHAR(80), TARGET_ID VARCHAR(100), CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
